export function createRobFieldElectronFlows(edge) {
  const empty = () => ({ wires: [], inside: [] });
  return [
    { wires: [edge('cell.neg', 'boost.inNeg'), edge('boost.outNeg', 'bus.neg'), edge('bus.pos', 'boost.outPos'), edge('boost.inPos', 'cell.pos')], inside: [edge('boost.inNeg', 'boost.inPos'), edge('boost.outNeg', 'boost.outPos'), edge('bus.neg', 'bus.pos'), edge('cell.pos', 'cell.neg')] },
    { wires: [edge('source.neg', 'bus.neg'), edge('bus.pos', 'fuse.out'), edge('fuse.in', 'source.pos')], inside: [edge('bus.neg', 'bus.pos'), edge('fuse.out', 'fuse.in'), edge('source.pos', 'source.neg')] },
    { wires: [edge('bus.neg', 'ring.nIn'), edge('ring.nOut', 'torso.neg'), edge('torso.pos', 'ring.pOut'), edge('ring.pIn', 'bus.pos')], inside: [edge('ring.nIn', 'ring.nOut'), edge('torso.neg', 'torso.pos'), edge('ring.pOut', 'ring.pIn'), edge('bus.pos', 'bus.neg')] },
    { wires: [edge('bus.neg', 'driver.gnd'), edge('driver.lb', 'left.b'), edge('left.a', 'driver.la'), edge('driver.vm', 'bus.pos')], inside: [edge('driver.gnd', 'driver.lb'), edge('left.b', 'left.a'), edge('driver.la', 'driver.vm'), edge('bus.pos', 'bus.neg')] },
    { wires: [edge('bus.neg', 'stepper.gnd'), edge('stepper.vm', 'bus.pos')], inside: [edge('stepper.gnd', 'stepper.vm'), edge('bus.pos', 'bus.neg')] },
    empty(),
    { wires: [edge('fixed.neg', 'ring.nIn'), edge('ring.nOut', 'rotating.neg'), edge('rotating.pos', 'ring.pOut'), edge('ring.pIn', 'fixed.pos')], inside: [edge('ring.nIn', 'ring.nOut'), edge('rotating.neg', 'rotating.pos'), edge('ring.pOut', 'ring.pIn'), edge('fixed.pos', 'fixed.neg')] },
    ...Array.from({ length: 7 }, empty),
    { wires: [edge('source.neg', 'buck12.inNeg'), edge('buck12.outNeg', 'test.neg'), edge('test.pos', 'buck12.outPos'), edge('buck12.inPos', 'source.pos')], inside: [edge('buck12.inNeg', 'buck12.inPos'), edge('buck12.outNeg', 'buck12.outPos'), edge('test.neg', 'test.pos'), edge('source.pos', 'source.neg')] },
    { wires: [edge('rail.neg', 'inverter.dcNeg'), edge('inverter.dcPos', 'fuse.out'), edge('fuse.in', 'rail.pos')], inside: [edge('inverter.dcNeg', 'inverter.dcPos'), edge('fuse.out', 'fuse.in'), edge('rail.pos', 'rail.neg')] },
    ...Array.from({ length: 4 }, empty),
    { wires: [edge('source.neg', 'boost48.inNeg'), edge('boost48.outNeg', 'test.neg'), edge('test.pos', 'boost48.outPos'), edge('boost48.inPos', 'source.pos')], inside: [edge('boost48.inNeg', 'boost48.inPos'), edge('boost48.outNeg', 'boost48.outPos'), edge('test.neg', 'test.pos'), edge('source.pos', 'source.neg')] },
    { wires: [edge('bus.neg', 'leftArm.return'), edge('leftArm.power', 'contactor.out'), edge('contactor.in', 'fuse.out'), edge('fuse.in', 'bus.pos')], inside: [edge('leftArm.return', 'leftArm.power'), edge('contactor.out', 'contactor.in'), edge('fuse.out', 'fuse.in'), edge('bus.pos', 'bus.neg')] },
    ...Array.from({ length: 8 }, empty),
  ];
}
